## 🟠 4️⃣ Ultrasonic Sensor (Distance Measurement)
```cpp
#include <ESP8266WiFi.h>
#include <ThingSpeak.h>

const char* ssid = "MaharshiJD";
const char* pass = "#include<iostream.h>";
unsigned long channel = 3147692;
const char* api = "W5V2C1XYY3HJS7OZ";

#define TRIG D5
#define ECHO D6
WiFiClient client;

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);

  WiFi.begin(ssid, pass);
  Serial.print("Connecting");
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.println("\nConnected!");
  ThingSpeak.begin(client);
}

void loop() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  long duration = pulseIn(ECHO, HIGH);
  float distance = duration * 0.034 / 2;

  Serial.printf("Distance: %.2f cm\n", distance);

  ThingSpeak.setField(5, distance);
  ThingSpeak.writeFields(channel, api);

  delay(20000);
}
```

